/* global chrome, browser */

import { options } from './base.js';
import * as dom from './dom.js';
import './fields.js';
import h from './hyperscript.js';
import * as util from './util.js';

// Expose this library.
options.util = util;
options.dom = dom;
options.h = h;
options.opts = {
  // If not given, title of the page will be set to the extension's name.
  // Set to `false` if you want to hide the title.
  title: null,

  // Set this if you want to customize the about tab's contents,
  // otherwise it will be set to the extension's description.
  // Set to `false` if you don't want an About page.
  about: null,

  // True if you want settings to be saved as they are changed.
  autoSave: true,

  // True if you want default values to be saved when user visits
  // the options page. Useful if you want to only specify default values
  // in one place, without having to check if an option is set.
  // Note that it requires the options page to be visited once.
  saveDefaults: true,

  // Pluggable storage: area name (e.g. 'sync', 'local', 'managed') or
  // custom storage object with get() and set() methods. Defaults to auto-detecting
  // browser.storage.sync, chrome.storage.sync, or falling back to localStorage.
  storage: null,

  // Custom manifest object to use instead of reading from extension runtime.
  manifest: null,
};

const normalizeKeys = (keys) => {
  if (keys === null || keys === undefined || typeof keys === 'function') {
    return null;
  }
  if (typeof keys === 'string') {
    return [keys];
  }
  if (Array.isArray(keys)) {
    return keys;
  }
  if (typeof keys === 'object') {
    return Object.keys(keys);
  }
  return [String(keys)];
};

const applyDefaults = (result, defaults) => {
  if (!defaults || typeof defaults !== 'object' || Array.isArray(defaults)) {
    return result || {};
  }
  const merged = Object.assign({}, defaults);
  for (const [k, v] of Object.entries(result || {})) {
    if (v !== undefined) {
      merged[k] = v;
    }
  }
  return merged;
};

const memoryStore = {};
const defaultFallbackStorage = {
  get: (keys, cb) => {
    if (typeof keys === 'function') {
      cb = keys;
      keys = null;
    }
    let result = {};
    const defaults =
      keys && typeof keys === 'object' && !Array.isArray(keys) ? keys : null;
    let targetKeys = normalizeKeys(keys);

    if (targetKeys === null) {
      const allKeys = new Set(Object.keys(memoryStore));
      try {
        if (typeof localStorage !== 'undefined') {
          for (let i = 0; i < localStorage.length; i++) {
            const k = localStorage.key(i);
            if (k) {
              allKeys.add(k);
            }
          }
        }
      } catch {
        // ignore storage errors
      }
      targetKeys = Array.from(allKeys);
    }

    targetKeys.forEach((key) => {
      let item = null;
      try {
        if (typeof localStorage !== 'undefined') {
          item = localStorage.getItem(key);
        }
      } catch {
        item = null;
      }
      if (item !== null) {
        try {
          result[key] = JSON.parse(item);
        } catch {
          result[key] = item;
        }
      } else if (Object.hasOwn(memoryStore, key)) {
        result[key] = memoryStore[key];
      }
    });

    if (defaults) {
      result = applyDefaults(result, defaults);
    }

    if (cb) {
      cb(result);
    }
    return result;
  },
  set: (items, cb) => {
    let saved = false;
    try {
      if (typeof localStorage !== 'undefined') {
        for (const [key, value] of Object.entries(items || {})) {
          localStorage.setItem(key, JSON.stringify(value));
        }
        saved = true;
      }
    } catch {
      saved = false;
    }
    if (!saved) {
      for (const [key, value] of Object.entries(items || {})) {
        memoryStore[key] = value;
      }
    }
    if (cb) {
      cb();
    }
  },
};

const invokeStorageMethod = (fn, args, onDone) => {
  let called = false;
  const done = (val) => {
    if (!called) {
      called = true;
      onDone(val);
    }
  };

  try {
    const ret = fn(...args, done);
    if (ret && typeof ret.then === 'function') {
      ret.then(done).catch((err) => {
        console.error(err);
        done(undefined);
      });
    } else if (ret !== undefined && !called) {
      done(ret);
    }
  } catch (err) {
    console.error(err);
    done(undefined);
  }
};

const resolveStorageTarget = (target) => {
  if (target && typeof target === 'object') {
    return target;
  }
  if (typeof target === 'string') {
    if (typeof browser !== 'undefined' && browser?.storage?.[target]) {
      return browser.storage[target];
    }
    if (typeof chrome !== 'undefined' && chrome?.storage?.[target]) {
      return chrome.storage[target];
    }
    return defaultFallbackStorage;
  }
  if (typeof browser !== 'undefined') {
    if (browser?.storage?.sync) return browser.storage.sync;
    if (browser?.storage?.local) return browser.storage.local;
  }
  if (typeof chrome !== 'undefined') {
    if (chrome?.storage?.sync) return chrome.storage.sync;
    if (chrome?.storage?.local) return chrome.storage.local;
  }
  return defaultFallbackStorage;
};

let cachedStorageTarget = null;
let cachedStorageAdapter = null;

const getStorage = () => {
  const target = resolveStorageTarget(options.opts.storage);

  if (cachedStorageTarget === target && cachedStorageAdapter) {
    return cachedStorageAdapter;
  }

  cachedStorageTarget = target;
  cachedStorageAdapter = {
    get: (keys, callback) => {
      if (typeof keys === 'function') {
        callback = keys;
        keys = null;
      }
      const query = keys === undefined ? null : keys;
      invokeStorageMethod(target.get.bind(target), [query], (result) => {
        let res = result || {};
        if (keys && typeof keys === 'object' && !Array.isArray(keys)) {
          res = applyDefaults(res, keys);
        }
        if (callback) {
          callback(res);
        }
      });
    },
    set: (items, callback) => {
      invokeStorageMethod(target.set.bind(target), [items], () => {
        if (callback) {
          callback();
        }
      });
    },
  };

  return cachedStorageAdapter;
};

const getManifest = () => {
  if (options.opts.manifest) {
    return options.opts.manifest;
  }
  try {
    if (typeof browser !== 'undefined' && browser?.runtime?.getManifest) {
      return browser.runtime.getManifest();
    }
    if (typeof chrome !== 'undefined' && chrome?.runtime?.getManifest) {
      return chrome.runtime.getManifest();
    }
  } catch {
    // ignore runtime errors
  }
  return {};
};

const $menu = document.querySelector('#main-menu');
const $mainview = document.querySelector('.mainview');
let lastHash = null;
let hashPath = window.location.hash.split('.');

const menuClick = () => {
  const newHash = window.location.hash;
  if (!newHash) {
    document
      .querySelector('.mainview > *:nth-child(2)')
      .classList.add('selected');
    document
      .querySelector('#main-menu li:first-child')
      .classList.add('selected');
    return;
  }
  if (newHash === lastHash) {
    return;
  }
  lastHash = newHash;

  document.querySelectorAll('.mainview > *, .menu li').forEach((el) => {
    el.classList.remove('selected');
  });

  hashPath = newHash.split('.');

  const $currentView = document.querySelector(hashPath[0]);
  if ($currentView) {
    document
      .querySelector(`.menu a[href="${hashPath[0]}"]`)
      .parentNode.classList.add('selected');
    $currentView.classList.add('selected');
    document.body.scrollTop = 0;
  }
};

setTimeout(menuClick, 100);
window.addEventListener('hashchange', menuClick);

const urlParams = {};
window.location.search
  .substring(1)
  .split('&')
  .forEach((param) => {
    urlParams[param] = true;
  });

const changedValues = {};
const $saveContainer = document.querySelector('.save-container');
const $saveButton = $saveContainer.querySelector('button');
$saveButton.addEventListener('click', () => {
  getStorage().set(changedValues, () => {
    $saveButton.setAttribute('disabled', true);
  });
});
const showSavedAlert = dom.flashClass($saveContainer, 'show', 2000);
const flashSavedAlert = dom.flashClass($saveContainer, 'flash', 150);

// Add the extension's title to the top of the page.
let setupRan = false;
const setup = () => {
  if (setupRan) {
    return;
  }
  const manifest = getManifest();

  const extensionName = options.opts.title || manifest.name || 'web extension';
  document.querySelector('title').textContent = `${extensionName} options`;
  const $title = document.querySelector('.web-extension-options-title');
  if ($title) {
    $title.textContent = extensionName;
  }
  if (options.opts.title !== false && !urlParams.hideTitle) {
    document.body.classList.add('show-title');
  }

  const description = manifest.description;
  if (
    options.opts.about !== false &&
    (options.opts.about || description) &&
    !urlParams.hideAbout
  ) {
    document.body.classList.add('show-about');
    const $about = document.querySelector('#about .content > p');
    if (options.opts.about) {
      $about.innerHTML = options.opts.about;
    } else {
      $about.textContent = description;
    }
  }

  if (!manifest.options_ui || manifest.options_ui.open_in_tab) {
    document.body.classList.add('open-in-tab');
  }

  if (!urlParams.hideSidebar) {
    document.body.classList.add('show-sidebar');
  }

  if (!urlParams.hideTabTitle) {
    document.body.classList.add('show-tab-title');
  }

  if (!urlParams.hideTabDesc) {
    document.body.classList.add('show-tab-desc');
  }

  if (options.opts.autoSave) {
    $saveButton.style.display = 'none';
  } else {
    $saveContainer.querySelector('.auto').style.display = 'none';
    $saveContainer.classList.add('show');
  }

  setupRan = true;
};

const isLayoutOption = (option) =>
  option.type === 'column' || option.type === 'row';

const getKeyPath = (tabKey, option) => {
  return (tabKey ? `${tabKey}.` : '') + (option.name || '');
};

/**
 * @param {string} name
 * @param {!string} desc Will be placed at the top of the page of the tab
 * @param {Array.<Object>} tabOptions
 */
options.addTab = (name, desc, tabOptions) => {
  setup();
  if (!tabOptions) {
    tabOptions = desc;
    desc = null;
  }
  const tabKey = name.toLowerCase().replace(' ', '_');
  const $menuButton = h('li', h('a', { href: `#${tabKey}` }, name));
  $menuButton.querySelector('a').addEventListener('click', menuClick);
  $menu.append($menuButton);
  const $tabview = h('div', { id: tabKey }, h('header', h('h1', name)));
  const $tabcontent = h('div.content');
  if (desc) {
    $tabcontent.append(h('p.tab-desc', desc));
  }

  // If hash contains a specific option to display,
  // only display that one option.
  if (hashPath.length && hashPath[0].length) {
    const tabHashPath = tabKey.length
      ? hashPath.slice(1)
      : [hashPath[0].replace(/^#/, '')].concat(hashPath.slice(1));
    const filterOptions = (optionsList = [], depth) => {
      if (tabHashPath.length <= depth) {
        return optionsList;
      }
      return optionsList
        .filter((option) => {
          // Allow layout based options.
          return isLayoutOption(option) || option.name === tabHashPath[depth];
        })
        .map((option) => {
          option = Object.assign({}, option);
          const nextDepth = option.name ? depth + 1 : depth;
          option.options = filterOptions(option.options, nextDepth);
          return option;
        });
    };
    tabOptions = filterOptions(tabOptions, 0);
  }

  const keys = [];
  const getOptionKeys = (list) => {
    list.forEach((option) => {
      if (option.name) {
        keys.push(getKeyPath(tabKey, option));
      } else if (isLayoutOption(option)) {
        getOptionKeys(option.options);
      }
    });
  };
  getOptionKeys(tabOptions);

  getStorage().get(keys, (items) => {
    $tabcontent.append(addTabOptions(tabKey, items, tabOptions));
  });
  $tabview.append($tabcontent);
  $mainview.append($tabview);
};

/**
 * @param {!string} desc
 * @param {Array.<Object>} tabOptions
 */
options.set = (desc, tabOptions) => {
  urlParams.hideSidebar = true;
  urlParams.hideTabTitle = true;
  options.addTab('', desc, tabOptions);
};

const addTabOptions = (tabKey, values, tabOptions) => {
  return h(
    '',
    tabOptions.map((option) => {
      const key = getKeyPath(tabKey, option);
      const isLayout = isLayoutOption(option);
      let value = isLayout ? values : values[key];
      let latestValue = value;

      // Clone value so that it can be compared to new value.
      const cloneValue = () => {
        value = util.deepClone(latestValue);
      };
      $saveButton.addEventListener('click', cloneValue);

      // Use requestAnimationFrame whenever possible,
      // so that it doensn't seep into load time.
      requestAnimationFrame(cloneValue);

      let duringLoad = true;
      const save = (newValue) => {
        const autoSave = options.opts.autoSave || duringLoad;
        requestAnimationFrame(() => {
          latestValue = newValue;
          const isEqual = util.deepEqual(value, newValue);
          const valueToSave = isLayout ? newValue : { [key]: newValue };
          if (autoSave) {
            if (!isEqual) {
              getStorage().set(valueToSave);
              showSavedAlert();
              flashSavedAlert();
              cloneValue();
            }
          } else if (isEqual) {
            for (const optionKey in valueToSave) {
              delete changedValues[optionKey];
            }
            if (!Object.keys(changedValues).length) {
              $saveButton.setAttribute('disabled', true);
            } else {
              flashSavedAlert();
            }
          } else {
            Object.assign(changedValues, valueToSave);
            $saveButton.removeAttribute('disabled');
            flashSavedAlert();
          }
        });
      };
      const $option = options.addOption(key, value, save, option);
      duringLoad = false;
      return $option;
    }),
  );
};

if (typeof window !== 'undefined') {
  window.webExtensionOptions = options;
}

options.default = options;

module.exports = options;
